DO $bg$
DECLARE packs jsonb := $pack$[{"modo":"HEREDA","tipo":"CAMBIO","clase":"PANTALLA","clave":"s22ao_legacy_13139_0","dueno":"PRODUCTO","codigo":"S22AO-13139-1","efecto":"BLOQUEAR","origen":{"ref":"lf_ops.reglas/13139","tipo":"MIGRACION","solicitante":"Cristhian / Claude S22-BG D01-D06 D04b"},"titulo":"Procesamiento parcial: solo válidos — candidato de reemplazo gobernado","alcance":"B2B_CARGAS","familia":"B2B_PORTFOLIO_LOADS","impacto":"REVISAR","autoridad":"LEG-PRODUCTO","condicion":{"op":"o","izq":{"op":"y","izq":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_b2b_mixed_validation"}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_unconfirmed_terms_committed"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_segment_overlap"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_company_distribution_forced_regroup"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_assisted_segment_coverage_invalid"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_final_receipt_missing"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_duplicate_summary"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_reupload_not_independent"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_current_load_mutated"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_original_values_changed"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_export_missing_or_wrong"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_cta_wrong"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_alerts_counted_as_invalid"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_reconciliation_wrong"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_excluded_not_traceable"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_excluded_not_reported"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_invalid_rows_processed"}},"izq":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_valid_rows_stopped"}}}}}}}}}}}}}}}}}},"der":{"op":"=","izq":{"hecho":"bg_invalid_plan_not_excluded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_invalid_initial_not_excluded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_segment_terms_incomplete"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_segment_assignment_contract_wrong"},"der":{"lit":true}}}},"der":{"op":"o","izq":{"op":"=","izq":{"hecho":"bg_invalid_plan_not_excluded"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"bg_invalid_initial_not_excluded"},"der":{"lit":true}}}},"naturaleza":"CONDUCTA","descripcion":"Los registros válidos continúan aunque existan registros observados, rechazados o duplicados. Los registros inválidos se excluyen, reportan y mantienen trazabilidad. En cargas de cuotas, el plan constituye la unidad económica de validación. Cualquier cuota inválida o pago inicial no válido determina la exclusión del plan completo, sin impedir el procesamiento de otros planes válidos. El total de registros debe conciliar con los válidos y excluidos, utilizando una unidad de conteo consistente. Las alertas de negocio son un subconjunto de los válidos y no constituyen registros adicionales. La continuación se habilita únicamente cuando concluye la validación y existen registros válidos. El reporte de errores contiene exclusivamente los excluidos, conserva los valores originales, identifica las celdas afectadas y reúne todas las incidencias detectables mediante una explicación y acción sugerida. Su descarga requiere el permiso autorizado B2B_LOAD_ERRORS_DOWNLOAD. Las correcciones constituyen una nueva carga independiente, sin modificar una carga previamente validada. La segmentación utiliza los ejes requeridos y admite una dimensión adicional cuando existen datos disponibles. Cada registro pertenece como máximo a un segmento y, en modalidad asistida, todos los registros válidos deben quedar asignados. La empresa puede seleccionar grupos, editar rangos y agruparlos en segmentos. Cuando la distribución proviene de una carga completa autorizada, LF conserva sus términos sin imponer una nueva agrupación. Cada segmento asistido debe tener las condiciones comerciales requeridas antes de completar la carga. Se permiten ofertas de pago único por importe fijo o porcentaje, planes alternativos de cuotas o ambas modalidades cuando estén autorizadas. LF genera los importes y presenta las condiciones para confirmación expresa antes de aplicarlas. El resultado final reutiliza B2B-CARGA-003 como recibo de procesamiento y permite descargar el resultado, sin duplicar el resumen de validación ni convertir la pantalla final en una búsqueda individual de deudores. Binding runtime pendiente; no modifica IG ni materializa estructuras pendientes.","pruebas":[{"entrada":{"ao_b2b_mixed_validation":true,"ao_unconfirmed_terms_committed":false,"ao_segment_overlap":false,"ao_company_distribution_forced_regroup":false,"ao_assisted_segment_coverage_invalid":false,"ao_final_receipt_missing":false,"ao_duplicate_summary":false,"ao_reupload_not_independent":false,"ao_current_load_mutated":false,"ao_original_values_changed":false,"ao_export_missing_or_wrong":false,"ao_cta_wrong":false,"ao_alerts_counted_as_invalid":false,"ao_reconciliation_wrong":false,"ao_excluded_not_traceable":false,"ao_excluded_not_reported":false,"ao_invalid_rows_processed":false,"ao_valid_rows_stopped":false,"bg_invalid_plan_not_excluded":false,"bg_invalid_initial_not_excluded":false,"bg_segment_terms_incomplete":false,"bg_segment_assignment_contract_wrong":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"},{"entrada":{"ao_b2b_mixed_validation":true,"ao_unconfirmed_terms_committed":true,"ao_segment_overlap":false,"ao_company_distribution_forced_reg