S"},"izq":{"hecho":"ao_default_max_terms"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_server_authority_missing"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_summary_replaces_schedule"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_file_plan_key_as_primary"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_missing_active_initial_auto_activated"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_window_hardcoded"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_snapshot_not_frozen"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_assistant_residual_not_last"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_external_schedule_changed"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_unapproved_company_limit_override"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_terms_not_company_allowed"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_offer_amount_wrong"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_regular_period_not_next"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_paid_initial_not_confirmed"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_client_label_wrong"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_initial_payment_regular_schedule"}},"izq":{"op":"o","der":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_alternative_amounts_aggregated"}},"izq":{"op":"=","der":{"lit":true},"izq":{"hecho":"ao_plan_identity_missing"}}}}}}}}}}}}}}}}}}}}},"der":{"op":"=","izq":{"hecho":"bg_installment_number_invalid"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_initial_amount_invalid"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_invalid_initial_not_excluded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_due_dates_not_lf_generated"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_initial_card_amount_wrong"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_initial_manual_partial_activated"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_initial_manual_partial_not_recorded"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_initial_expired_refund_missing"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_plan_change_unauthorized"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"bg_paid_installment_or_history_mutated"},"der":{"lit":true}}},"der":{"op":"y","izq":{"op":">","izq":{"hecho":"ao_initial_payment_amount"},"der":{"lit":0}},"der":{"op":"<=","izq":{"hecho":"ao_initial_payment_amount"},"der":{"param":"B2B.INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE"}}}}},"naturaleza":"CONDUCTA","descripcion":"Cada alternativa económica tiene identidad interna propia y un monto acordado independiente. No se agregan importes de alternativas no seleccionadas. La referencia del archivo de carga permite relacionar información, pero no sustituye la identidad interna del plan. La cuota 0 representa internamente el pago inicial y se presenta al cliente como «Pago inicial». No integra el conteo regular. La numeración es única y consecutiva dentro del plan; la cuota 1 corresponde a la primera cuota regular. El pago inicial es opcional. Es válido únicamente cuando es cero, lo que significa que no existe pago inicial activo, o cuando supera {param:B2B.INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE}. Si el importe inicial es positivo y menor o igual a {param:B2B.INITIAL_PAYMENT_ACTIVE_MIN_EXCLUSIVE}, se rechaza el plan completo con el motivo «pago inicial no válido» en el reporte de excluidos. Los demás planes válidos continúan. El pago inicial y las cuotas regulares deben conciliar exactamente con el monto económico acordado, conforme a la precisión monetaria gobernada. La cantidad de cuotas regulares se deriva del cronograma detallado, debe coincidir con la cantidad declarada y pertenecer al conjunto autorizado por la empresa. El límite base se obtiene de {param:B2B.INSTALLMENT_DEFAULT_MAX_TERMS}; cualquier ampliación exige autorización empresarial. El Asistente solo propone cantidades habilitadas. LF conserva los importes proporcionados por la empresa. Cuando el Asistente genera los importes, el residuo del redondeo se absorbe exclusivamente en la última cuota regular. En ambos formatos Excel, LF genera las fechas conforme a la ventana mínima y los ciclos autorizados por la empresa. Si la siguiente fecha permitida no satisface la ventana mínima, utiliza el siguiente ciclo elegible. El cronograma es propuesto antes de activar el plan y definitivo después de confirmarse el evento de activación autorizado. Cuando existe pago inicial activo, el plan solo se activa al confirmar el importe exigido completo. El pago inicial por tarjeta debe ser exacto y no admite pagos parciales. Los abonos manuales inferiores al importe exigido se registran como recibidos, sin activar el plan hasta completar el pago inicial. Si vence el plazo autorizado sin completarlo, el plan no se activa y se devuelve lo abonado. Cuando no existe pago inicial activo, el plan solo puede activarse mediante confirmación expresa del cliente. Un plan contratado únicamente puede modificarse mediante renegociación autorizada. Las cuotas pagadas permanecen intactas y las condiciones anteriores se conservan como historial. El backend resuelve las condiciones económicas y el cronograma. El frontend presenta los resultados sin recalcularlos. La confirmación efectiva del pago determina cuándo puede mostrarse como pagado. Binding runtime pendiente; no modifica IG ni materializa estructuras pendientes.","pruebas":[{"entrada":{"ao_installment_plan":true,"ao_initial_active_claim":false,"ao_initial_payment_amount":0,"ao_default_max_terms":{"param":"B2B.INSTALLMENT_DEFAULT_MAX_TERMS","mas":0},"ao_server_authority_missing":false,"ao_summary_replaces_schedule":false,