e,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":true,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":false,"aq_mora_not_company_config":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":true,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":true,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":false,"aq_mora_not_company_config":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":true,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":true,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":false,"aq_mora_not_company_config":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":true,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":true,"aq_mora_hardcoded":false,"aq_mora_not_company_config":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":true,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":true,"aq_mora_not_company_config":false},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":true,"s22s05_implementa_o_contabiliza_sin_autorizacion":false,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":false,"aq_mora_not_company_config":true},"esperado":true,"casuistica":"SE_CUMPLE"},{"entrada":{"s22s05_evalua_outcome_cuota":false,"s22s05_implementa_o_contabiliza_sin_autorizacion":true,"s22s05_cancelacion_sin_parametro":false,"s22s05_conciliacion_o_escalamiento_invalido":false,"s22s05_fecha_gracia_o_timezone_invalida":false,"s22s05_rechazo_o_falla_como_vencido":false,"s22s05_pendiente_admite_nuevo_intento":false,"s22s05_confirmacion_o_estado_invalido":false,"bg_installment_initial_state_wrong":false,"bg_in_process_cancelled":false,"bg_age_cancelled_collectible":false,"aq_mora_charged_without_config":false,"aq_mora_hardcoded":false,"aq_mora_not_company_config":false},"esperado":false,"casuistica":"NO_SE_CUMPLE"}]}]$pack$::jsonb;
 a jsonb; ans jsonb; cd text; t record; h text; hashes jsonb:='{}'; vectors int:=0; n int:=0;
 before_replaced bigint; after_replaced bigint; b_leg jsonb; b_cfg jsonb; b_cov jsonb; b_rules jsonb; b_apps jsonb; b_other_versions jsonb; b_saly jsonb; suite text:=''; verdict text; val jsonb; lid int; links int:=0; b_v1 jsonb;
BEGIN
 SELECT jsonb_object_agg(regla,to_jsonb(x)-'vigente_hasta') INTO b_v1 FROM lf_ops.nucleo_regla_versiones x WHERE regla IN ('S22AO-13139-1','S22AO-617-1','S22AO-617-2','S22AO-620-1','S22S-C05') AND version=1;
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) INTO b_cov FROM lf_ops.lf_nucleo_cobertura_legada x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) INTO b_rules FROM lf_ops.nucleo_reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,nodo) INTO b_apps FROM lf_ops.nucleo_aplicaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_other_versions FROM lf_ops.nucleo_regla_versiones x WHERE regla NOT IN ('S22AO-13139-1','S22AO-617-1','S22AO-617-2','S22AO-620-1','S22S-C05');
 SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_reglas x),'versions',(SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM saly.nucleo_regla_versiones x),'facts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_hechos x)) INTO b_saly;
 IF (SELECT count(*) FROM lf_ops.reglas)=586 AND before_replaced<>517 THEN RAISE EXCEPTION 'S22BG_PROD_COVERAGE_DRIFT %',before_replaced; END IF;
 IF EXISTS(SELECT 1 FROM saly.nucleo_reglas WHERE codigo IN ('S22AO-13139-1','S22AO-617-1','S22AO-617-2','S22AO-620-1','S22S-C05')) THEN RAISE EXCEPTION 'S22BG_SALY_SCOPE'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(packs) LOOP
 cd:=a->>'codigo';
 IF NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_reglas WHERE codigo=cd AND capa_ejecucion=CASE WHEN cd='S22S-C05' THEN 'BACKEND' ELSE 'AMBOS' END) OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='PUBLICADA' AND vigente_hasta IS NULL) THEN RAISE EXCEPTION 'S22BG_BASELINE %',cd; END IF;
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22BG_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 2 THEN RAISE EXCEPTION 'S22BG_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,2);
 IF h IS NULL THEN RAISE EXCEPTION 'S22BG_HASH_MISSING %',cd; END IF;
 hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=2 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22BG_VECTOR_FAIL %',cd; END IF;
 vectors:=vectors+1; END LOOP;

 n:=n+1;
 END LOOP;
 IF n<>5 OR vectors<>140 THEN RAISE EXCEPTION 'S22BG_VECTOR_COUNT % %',n,vectors; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY legacy_id,nucleo_codigo,version_nucleo) FROM lf_ops.lf_nucleo_cobertura_legada x) IS DISTINCT FROM b_cov OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM lf_ops.nucleo_reglas x) IS DISTINCT FROM b_rules OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,nodo) FROM lf_ops.nucleo_aplicaciones x) IS DISTINCT FROM b_apps OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_regla_versiones x WHERE regla NOT IN ('S22AO-13139-1','S22AO-617-1','S22AO-617-2','S22AO-620-1','S22S-C05')) IS DISTINCT FROM b_other_versions THEN RAISE EXCEPTION 'S22BG_INVARIANT_FAIL'; END IF;
 IF (SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_reglas x),'versions',(SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM saly.nucleo_regla_versiones x),'facts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY codigo) FROM saly.nucleo_hechos x))) IS DISTINCT FROM b_saly THEN RAISE EXCEPTION 'S22BG_SALY_DRIFT'; END IF;
 SELECT count(DISTINCT legacy_id) INTO after_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 IF after_replaced<>before_replaced THEN RAISE EXCEPTION 'S22BG_COVERAGE_DRIFT'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22BG_DPIG03'; END IF;
 FOR t IN SELECT * FROM (VALUES ('lf_ops','puerta','PUERTA 26/26'),('lf_ops','evaluacion','EVALUACION 23/23'),('lf_ops','cambio','CAMBIO 16/16'),('lf_ops','contrato','CONTRATO 4/4 (12 casos)'),('lf_ops','calculo','CALCULO 36/36'),('lf_ops','profundidad','PROFUNDIDAD 13/13'),('lf_ops','alcance_inverso','ALCANCE_INVERSO 10/10'),('saly','puerta','PUERTA 26/26'),('saly','evaluacion','EVALUACION 23/23'),('saly','cambio','CAMBIO 16/16'),('saly','contrato','CONTRATO 4/4 (12 casos)'),('saly','calculo','CALCULO 36/36'),('saly','profundidad','PROFUNDIDAD 13/13'),('saly','alcance_inverso','ALCANCE_INVERSO 10/10')) x(esquema,nombre,esperado) LOOP
 EXECUTE format('SELECT %I.%I()',t.esquema,'nucleo_autotest_'||t.nombre||'_v1') INTO verdict;
 IF verdict IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22BG_AUTOTEST_FAIL %.% %',t.esquema,t.nombre,verdict; END IF;
 suite:=concat_ws(';',suite,t.esquema||'.'||verdict);
 END LOOP;
 IF public.lf_nucleo_autotest_conjunto_v1() IS DISTINCT FROM 'CONJUNTO 5/5' OR lf_ops.lf_puente_autotest_v1() IS DISTINCT FROM 'PUENTE 8/8' OR lf_ops.lf_puente2_autotest_v1() IS DISTINCT FROM 'PUENTE2 6/6' THEN RAISE EXCEPTION 'S22BG_CONJUNTO_OR_PUENTE_FAIL'; END IF;

 RAISE NOTICE 'S22BG_PROOF PG=% CAMBIO=% VECTORES=% coverage_before=% coverage_after=% SALY_UNCHANGED DPIG03=0 J2=5/5 PUENTE=8/8 PUENTE2=6/6 suite=% hashes=%',current_setting('server_version_num'),n,vectors,before_replaced,after_replaced,suite,hashes;
END $bg$;
ROLLBACK;
DO $rollback$
BEGIN
 IF EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla IN ('S22AO-13139-1','S22AO-617-1','S22AO-617-2','S22AO-620-1','S22S-C05') AND version=2) OR EXISTS(SELECT 1 FROM lf_ops.nucleo_hechos WHERE codigo IN ('bg_invalid_plan_not_excluded','bg_invalid_initial_not_excluded','bg_segment_terms_incomplete','bg_segment_assignment_contract_wrong','bg_installment_number_invalid','bg_initial_amount_invalid','bg_due_dates_not_lf_generated','bg_initial_card_amount_wrong','bg_initial_manual_partial_activated','bg_initial_manual_partial_not_recorded','bg_initial_expired_refund_missing','bg_plan_change_unauthorized','bg_paid_installment_or_history_mutated','bg_complete_without_confirmation','bg_initial_or_identity_duplicated','bg_installment_initial_state_wrong','bg_in_process_cancelled','bg_age_cancelled_collectible')) THEN RAISE EXCEPTION 'S22BG_ROLLBACK_RESIDUE'; END IF;
 RAISE EXCEPTION 'S22BG_HASH_ALL ROLLBACK_OK; see S22BG_PROOF';
END $rollback$;
